<?php
namespace Modules\PriyasaCore\Jobs; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Modules\PriyasaCore\Models\CommerceConversationMessage; use Modules\PriyasaCore\Services\MetaWhatsAppService;
class SendWhatsAppMessage implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public function __construct(public int $messageId,public string $phone,public string $body){} public function handle(MetaWhatsAppService $meta){$m=CommerceConversationMessage::findOrFail($this->messageId); if($m->provider_message_id)return; $r=$meta->sendText($this->phone,$this->body); $id=$r['messages'][0]['id']??null; $m->update(['provider_message_id'=>$id,'provider_status'=>'sent','sent_at'=>now(),'metadata'=>array_merge((array)$m->metadata,['provider_response'=>$r])]);}}
